struct ListNode **listOfDepth(struct TreeNode *tree, int *returnSize) {
  struct ListNode **res = (struct ListNode **)malloc(sizeof(struct ListNode *) * 10000);
  *returnSize = 0;
  if (!tree) return res;
  struct TreeNode **queue = (struct TreeNode **)malloc(sizeof(struct TreeNode *) * 10000);
  int head = 0, tail = 0;
  queue[tail++] = tree;
  while (head < tail) {
    int levelSize = tail - head;
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode *lt = &dummy;
    for (int i = 0; i < levelSize; i++) {
      struct TreeNode *node = queue[head++];
      lt->next = (struct ListNode *)malloc(sizeof(struct ListNode));
      lt = lt->next;
      lt->val = node->val;
      lt->next = NULL;
      if (node->left) queue[tail++] = node->left;
      if (node->right) queue[tail++] = node->right;
    }
    res[(*returnSize)++] = dummy.next;
  }
  free(queue);
  return res;
}

class Solution {
public:
  vector<ListNode *> listOfDepth(TreeNode *tree) {
    vector<ListNode *> res;
    if (!tree) return res;
    queue<TreeNode *> q;
    q.push(tree);
    while (!q.empty()) {
      int levelSize = q.size();
      ListNode dummy(0);
      ListNode *lt = &dummy;
      for (int i = 0; i < levelSize; i++) {
        TreeNode *node = q.front();
        q.pop();
        lt->next = new ListNode(node->val);
        lt = lt->next;
        if (node->left) q.push(node->left);
        if (node->right) q.push(node->right);
      }
      res.push_back(dummy.next);
    }
    return res;
  }
};

func listOfDepth(tree *TreeNode) []*ListNode {
	res := []*ListNode{}
	if tree == nil {
		return res
	}
	queue := []*TreeNode{tree}
	for len(queue) > 0 {
		levelSize := len(queue)
		dummy := &ListNode{}
		lt := dummy
		for i := 0; i < levelSize; i++ {
			node := queue[0]
			queue = queue[1:]
			lt.Next = &ListNode{Val: node.Val}
			lt = lt.Next
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		res = append(res, dummy.Next)
	}
	return res
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public ListNode[] listOfDepth(TreeNode tree) {
    List<ListNode> res = new ArrayList<>();
    if (tree == null) return new ListNode[0];
    Queue<TreeNode> q = new ArrayDeque<>();
    q.add(tree);
    while (!q.isEmpty()) {
      int levelSize = q.size();
      ListNode dummy = new ListNode(0);
      ListNode lt = dummy;
      for (int i = 0; i < levelSize; i++) {
        TreeNode node = q.poll();
        lt.next = new ListNode(node.val);
        lt = lt.next;
        if (node.left != null) q.add(node.left);
        if (node.right != null) q.add(node.right);
      }
      res.add(dummy.next);
    }
    return res.toArray(new ListNode[0]);
  }
}

class Solution:
    def listOfDepth(self, tree: Optional[TreeNode]) -> List[Optional[ListNode]]:
        res = []
        if tree is None:
            return res
        q = deque([tree])
        while q:
            level_size = len(q)
            dummy = ListNode(0)
            lt = dummy
            for _ in range(level_size):
                node = q.popleft()
                lt.next = ListNode(node.val)
                lt = lt.next
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            res.append(dummy.next)
        return res

impl Solution {
  pub fn list_of_depth(tree: Option<Box<TreeNode>>) -> Vec<Vec<i32>> {
    let mut res = vec![];
    if tree.is_none() {
      return res;
    }
    let mut q: VecDeque<Box<TreeNode>> = VecDeque::new();
    q.push_back(tree.unwrap());
    while !q.is_empty() {
      let level_size = q.len();
      let mut level = vec![];
      for _ in 0..level_size {
        let node = q.pop_front().unwrap();
        level.push(node.val);
        if let Some(l) = node.left {
          q.push_back(l);
        }
        if let Some(r) = node.right {
          q.push_back(r);
        }
      }
      res.push(level);
    }
    res
  }
}

const listOfDepth = (tree: TreeNode | null): Array<ListNode | null> => {
  const res: Array<ListNode | null> = [];
  if (!tree) return res;
  let queue: TreeNode[] = [tree];
  while (queue.length > 0) {
    const levelSize = queue.length;
    const dummy = new ListNode(0);
    let lt: ListNode = dummy;
    for (let i = 0; i < levelSize; i++) {
      const node = queue.shift()!;
      lt.next = new ListNode(node.val);
      lt = lt.next;
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    res.push(dummy.next);
  }
  return res;
};
